package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.Locale;
final class CoreGlyph extends View {
 final int kind;final Paint p=new Paint(3);CoreGlyph(Context context,int value){super(context);kind=value;setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
 static int kind(String label){String s=label.toLowerCase(Locale.US);return s.equals("home")?1:s.equals("school")?2:s.equals("games")?3:s.equals("settings")?4:s.equals("apps")||s.equals("installed apps")?5:s.equals("calendar")?6:s.equals("notes")||s.equals("daily notes")?7:s.equals("create")?8:0;}
 protected void onDraw(Canvas c){c.save();c.scale(getWidth()/32f,getHeight()/32f);p.setColor(0xff111111);p.setStrokeWidth(2);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);if(kind==1){Path roof=new Path();roof.moveTo(3,14);roof.lineTo(16,3);roof.lineTo(29,14);c.drawPath(roof,p);c.drawRect(7,13,25,28,p);c.drawRect(13,20,19,28,p);}else if(kind==2){Path cap=new Path();cap.moveTo(2,11);cap.lineTo(16,4);cap.lineTo(30,11);cap.lineTo(16,18);cap.close();c.drawPath(cap,p);c.drawArc(new RectF(8,13,24,27),0,180,false,p);c.drawLine(29,12,29,23,p);}else if(kind==3){c.drawRoundRect(new RectF(3,9,29,26),6,6,p);c.drawLine(7,17,15,17,p);c.drawLine(11,13,11,21,p);c.drawCircle(22,15,1,p);c.drawCircle(25,20,1,p);}else if(kind==4){c.drawCircle(16,16,8,p);c.drawCircle(16,16,3,p);for(int i=0;i<8;i++){c.save();c.rotate(i*45,16,16);c.drawLine(16,3,16,7,p);c.restore();}}else if(kind==5){for(int y=5;y<=18;y+=13)for(int x=5;x<=18;x+=13)c.drawRoundRect(new RectF(x,y,x+9,y+9),2,2,p);}else if(kind==6){c.drawRoundRect(new RectF(4,6,28,28),3,3,p);c.drawLine(4,13,28,13,p);c.drawLine(10,3,10,9,p);c.drawLine(22,3,22,9,p);c.drawLine(10,19,13,19,p);c.drawLine(19,23,22,23,p);}else if(kind==7){c.drawRoundRect(new RectF(6,3,26,29),2,2,p);for(int y=10;y<=24;y+=7)c.drawLine(10,y,22,y,p);}else{c.drawLine(7,24,25,5,p);c.drawLine(12,28,29,10,p);c.drawOval(new RectF(3,22,12,30),p);}c.restore();}
}
